          "full_source_sha256": "9ec493983d1b4b41a043b5eb934563ca37c64e1f98a2bb88bca90a8e49b551c9",
          "offset_unit": "unicode code points in UTF-8 decoded original bytes",
          "full_source_characters": 9257,
          "context_characters": 2048,
          "windows": [
            {
              "raw_start": 0,
              "raw_end": 9257,
              "quotes": [
                {
                  "claim_id": "c15",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 1433,
                  "raw_end": 1450,
                  "text": "September 8, 2026"
                },
                {
                  "claim_id": "c12",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 1740,
                  "raw_end": 1874,
                  "text": "That means some people could have ankle-deep water in their yard by the time a flash flood warning notification sounds on their phone."
                },
                {
                  "claim_id": "c1",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 1970,
                  "raw_end": 2177,
                  "text": "Researchers at The University of Texas at San Antonio have developed a self-sustaining, artificial intelligence-powered flood warning system designed to spot dangerous water accumulation at the street level."
                },
                {
                  "claim_id": "c14",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 2668,
                  "raw_end": 2871,
                  "text": "Our system is an off-grid solution. It generates its own power, evaluates flood risk locally right on the device and sends timely warnings without needing external electricity or expensive network lines."
                },
                {
                  "claim_id": "c11",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 3204,
                  "raw_end": 3350,
                  "text": "This project was funded in part by a Texas Coastal Management Program grant awarded by the National Oceanic and Atmospheric Administration (NOAA)."
                },
                {
                  "claim_id": "c13",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 3692,
                  "raw_end": 3924,
                  "text": "Existing commercial flood-monitoring stations also come with drawbacks, from prohibitively high costs to reliance on grid power or frequent battery replacements, which leaves them vulnerable during multi-day storms or power outages."
                },
                {
                  "claim_id": "c2",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 3996,
                  "raw_end": 4156,
                  "text": "The resulting prototype combines temperature, humidity, light and precipitation sensing, as well as four optical water-level sensors mounted at varying heights."
                },
                {
                  "claim_id": "c18",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 4697,
                  "raw_end": 4888,
                  "text": "Pan\u2019s system sidesteps this roadblock by using TinyML \u2014 a branch of computer science that compresses machine learning algorithms so they can run directly on small, low-power microcontrollers."
                },
                {
                  "claim_id": "c3",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 4889,
                  "raw_end": 5026,
                  "text": "This on-device AI evaluates current and recent sensor data to predict localized, imminent flood risk without relying on a central server."
                },
                {
                  "claim_id": "c4",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
                  "raw_start": 5027,
                  "raw_end": 5136,
                  "text": "So far, the AI has performed well, achieving 98.82% validation accuracy in initial assessments post-training."
                },
                {
                  "claim_id": "c5",
                  "occurrence_index": 0,
                  "occurrence_count": 1,
